      ctx.beginPath(); ctx.arc(leftEyeX, eyeY, 5, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(rightEyeX, eyeY, 5, 0, Math.PI * 2); ctx.fill();

      // Intense slanted brows
      ctx.strokeStyle = 'black'; ctx.lineWidth = 4;
      ctx.beginPath(); ctx.moveTo(leftEyeX - 12, eyeY - 14); ctx.lineTo(leftEyeX + 4, eyeY - 6); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(rightEyeX + 12, eyeY - 14); ctx.lineTo(rightEyeX - 4, eyeY - 6); ctx.stroke();

      // Wide triumphant jagged grin
      ctx.fillStyle = 'white';
      ctx.beginPath();
      ctx.moveTo(centerX - 15, eyeY + 15);
      ctx.quadraticCurveTo(centerX, eyeY + 35, centerX + 15, eyeY + 15);
      ctx.fill();
      ctx.strokeStyle = 'black'; ctx.lineWidth = 2;
      ctx.stroke();
      // Teeth lines
      for(let i=0; i<3; i++) {
        ctx.beginPath(); ctx.moveTo(centerX - 8 + i*8, eyeY + 20); ctx.lineTo(centerX - 8 + i*8, eyeY + 28); ctx.stroke();
      }
    } else if (p.pushbackTimer > 0) {
      ctx.fillStyle = 'white';
      ctx.beginPath(); ctx.arc(leftEyeX, eyeY, eyeSize + 6, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(rightEyeX, eyeY, eyeSize + 6, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = 'black';
      ctx.beginPath(); ctx.arc(leftEyeX, eyeY, 3, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(rightEyeX, eyeY, 3, 0, Math.PI * 2); ctx.fill();
    } else if (p.invincibilityTimer > 0) {
      ctx.fillStyle = '#ffaaaa'; 
      ctx.beginPath(); ctx.arc(leftEyeX, eyeY, eyeSize + 4, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(rightEyeX, eyeY, eyeSize + 4, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = 'red';
      ctx.beginPath(); ctx.arc(leftEyeX, eyeY, 4, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(rightEyeX, eyeY, 4, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = '#ff0000'; ctx.lineWidth = 1;
      for (let i = 0; i < 4; i++) {
        const ang = i * Math.PI * 0.5;
        ctx.beginPath(); ctx.moveTo(leftEyeX, eyeY); ctx.lineTo(leftEyeX + Math.cos(ang) * 8, eyeY + Math.sin(ang) * 8); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(rightEyeX, eyeY); ctx.lineTo(rightEyeX + Math.cos(ang) * 8, eyeY + Math.sin(ang) * 8); ctx.stroke();
      }
      ctx.strokeStyle = 'black'; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.moveTo(leftEyeX - 10, eyeY - 12); ctx.lineTo(leftEyeX + 2, eyeY - 6); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(rightEyeX + 10, eyeY - 12); ctx.lineTo(rightEyeX - 2, eyeY - 6); ctx.stroke();
    } else if (p.killSatisfactionTimer > 0) {
      ctx.strokeStyle = 'black'; ctx.lineWidth = 3; 
      ctx.beginPath(); ctx.arc(leftEyeX, eyeY + 2, eyeSize + 2, Math.PI, 0); ctx.stroke(); 
      ctx.beginPath(); ctx.arc(rightEyeX, eyeY + 2, eyeSize + 2, Math.PI, 0); ctx.stroke();
    } else { 
      ctx.strokeStyle = 'black'; ctx.lineWidth = 2.5;
      ctx.beginPath(); ctx.moveTo(leftEyeX - 7, eyeY); ctx.lineTo(leftEyeX + 7, eyeY); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(rightEyeX - 7, eyeY); ctx.lineTo(rightEyeX - 0, eyeY); ctx.stroke(); 
      ctx.beginPath(); ctx.moveTo(leftEyeX - 10, eyeY - 12); ctx.lineTo(leftEyeX + 2, eyeY - 6); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(rightEyeX + 10, eyeY - 12); ctx.lineTo(rightEyeX - 2, eyeY - 6); ctx.stroke();
    }
    ctx.restore();

    const gunX = p.facing === 1 ? drawX + drawW - 10 : drawX - 14, gunY = p.isDucking ? drawY + 10 : drawY + 25;
    if (!isFlashing) {
        if (currentWeapon === 'GUN') { ctx.fillStyle = '#333'; ctx.fillRect(gunX, gunY, 24, 10); } 
        else if (currentWeapon === 'BOULDER') { ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.arc(gunX + 12, gunY + 5, 12, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); }
        else if (currentWeapon === 'SHOTGUN') { ctx.fillStyle = '#00FFFF'; ctx.fillRect(gunX, gunY, 20, 12); }
        else if (currentWeapon === 'FLAMETHROWER') { ctx.fillStyle = '#444'; ctx.fillRect(gunX, gunY, 30, 14); ctx.fillStyle = '#FF4500'; ctx.fillRect(p.facing === 1 ? gunX + 30 : gunX - 5, gunY + 4, 5, 6); }
        else if (currentWeapon === 'TSUNAMI') { ctx.fillStyle = '#1E90FF'; ctx.fillRect(gunX, gunY, 32, 16); ctx.fillStyle = '#fff'; ctx.fillRect(p.facing === 1 ? gunX + 28 : gunX, gunY + 4, 4, 8); }
    }
    ctx.restore();
  };

  const drawBossSprite = (ctx: CanvasRenderingContext2D, e: Enemy, id: string | null) => {
      const { pos, width, height } = e; ctx.save(); ctx.translate(pos.x, pos.y);
      if (e.rotation) {
          ctx.translate(width / 2, height / 2);
          ctx.rotate(e.rotation);
          ctx.translate(-width / 2, -height / 2);
      }
      switch (id) {
        case 'Artie Avalanche':
            ctx.fillStyle = '#AED6F1'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeStyle = 'black'; ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7);
            ctx.fillStyle = '#f1c27d'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
            ctx.fillStyle = '#2E86C1'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, Math.PI, 0); ctx.fill(); ctx.stroke(); break;
        case 'Victor Volcano':
            ctx.fillStyle = '#BA4A00'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7);
            ctx.fillStyle = '#8b4513'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.3, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
            ctx.fillStyle = '#FF4500'; ctx.fillRect(width * 0.2, height * 0.2, width * 0.6, height * 0.1); break;
        case 'Ernie Earthquake':
            ctx.fillStyle = '#6E2C00'; ctx.fillRect(0, height * 0.3, width, height * 0.7); ctx.strokeRect(0, height * 0.3, width, height * 0.7);
            ctx.fillStyle = '#e0ac69'; ctx.fillRect(width * 0.2, 0, width * 0.6, height * 0.4); break;
        case 'Hector Hurricane':
            ctx.fillStyle = '#16A085'; ctx.fillRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7); ctx.strokeRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7);
            ctx.fillStyle = '#f1c27d'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); break;
        default: ctx.fillStyle = 'yellow'; ctx.fillRect(0, 0, width, height); break;
      }
      ctx.restore();
  };

  const draw = useCallback(() => {
    const canvas = canvasRef.current; if (!canvas) return; const ctx = canvas.getContext('2d'); if (!ctx) return; const state = gameStateRef.current;
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) { ctx.fillStyle = 'black'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT); return; }
    const { player, enemies, projectiles, particles, blocks, camera, pickups, damageNumbers } = state;
    const colors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };
    ctx.fillStyle = colors.bg; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save(); 
    if (state.screenShakeTimer > 0) {
      ctx.translate((Math.random()-0.5)*15, (Math.random()-0.5)*15);
    }
    ctx.translate(-camera.x, -camera.y);
    blocks.forEach(b => { 
        if (b.type === 'door') { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y - state.doorOpenAmount, b.w, b.h); } 
        else if (b.type === 'pit') { ctx.fillStyle = '#f00'; ctx.globalAlpha = 0.4; ctx.fillRect(b.x, b.y, b.w, 400); ctx.globalAlpha = 1; } 
        else { ctx.fillStyle = colors.ground; ctx.fillRect(b.x, b.y, b.w, b.h); ctx.strokeStyle = colors.accent; ctx.strokeRect(b.x, b.y, b.w, b.h); } 
    });
    pickups.forEach(p => {
        if (p.type.includes('health')) { ctx.fillStyle = 'red'; const thick = p.type === 'large_health' ? 10 : 5; ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height); ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick); } 
        else { ctx.fillStyle = 'yellow'; const thick = p.type === 'large_ammo' ? 12 : 6; ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height); ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick); }
    });

    state.bossVolcanoTelegraphs.forEach(v => {
       ctx.save();
       ctx.globalCompositeOperation = 'screen';
       ctx.fillStyle = `rgba(255, 100, 0, ${0.3 + Math.sin(state.frame * 0.2) * 0.2})`;
       if (v.type === 'ground') {
           ctx.fillRect(v.pos.x - 40, v.pos.y - 10, 80, 40);
           ctx.strokeStyle = '#FF4500'; ctx.lineWidth = 2; ctx.strokeRect(v.pos.x - 40, v.pos.y - 10, 80, 40);
       } else {
           ctx.fillRect(v.pos.x - 10, v.pos.y - 40, 40, 80);
           ctx.strokeStyle = '#FF4500'; ctx.lineWidth = 2; ctx.strokeRect(v.pos.x - 10, v.pos.y - 40, 40, 80);
       }
       ctx.restore();
    });

    state.bossVolcanoes.forEach(v => { ctx.save(); ctx.fillStyle = '#FF4500'; if (v.type === 'ground') ctx.fillRect(v.pos.x - 20, v.pos.y, 40, 20); else ctx.fillRect(v.pos.x, v.pos.y - 20, 20, 40); ctx.restore(); });
    enemies.forEach(e => {
      if (e.health <= 0 && !e.isBlownAway) return;
      ctx.save();
      if (e.isBlownAway) { ctx.translate(e.pos.x + e.width / 2, e.pos.y + e.height / 2); ctx.rotate(e.rotation || 0); ctx.translate(-(e.pos.x + e.width / 2), -(e.pos.y + e.height / 2)); } 
      else if (e.type === 'boss' && e.hitCooldown && e.hitCooldown > 0 && Math.floor(state.frame / 5) % 2 === 0) { ctx.globalAlpha = 0.4; }
      if (e.type === 'boss') { 
        if (e.bossState === 'hurricane') {
          ctx.save();
          const centerX = e.pos.x + e.width/2;
          const centerY = e.pos.y + e.height/2;
          const gradient = ctx.createRadialGradient(centerX, centerY, 50, centerX, centerY, 300);
          gradient.addColorStop(0, 'rgba(100, 100, 150, 0.4)');
          gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
          ctx.fillStyle = gradient;
          ctx.beginPath(); ctx.arc(centerX, centerY, 300, 0, Math.PI * 2); ctx.fill();
          ctx.strokeStyle = 'rgba(174, 214, 241, 0.6)';
          ctx.lineWidth = 1.5;
          for(let i=0; i<30; i++) {
             const rx = (Math.random()-0.5)*600;
             const ry = (Math.random()-0.5)*600;
             if (Math.sqrt(rx*rx + ry*ry) < 300) {
               ctx.beginPath();
               ctx.moveTo(centerX + rx, centerY + ry);
               ctx.lineTo(centerX + rx - 5, centerY + ry + 15);
               ctx.stroke();
             }
          }
          if (state.frame % 15 < 3) {
            ctx.strokeStyle = 'white';
            ctx.lineWidth = 3;
            ctx.beginPath();
            let lx = centerX + (Math.random()-0.5)*400;
            let ly = centerY - 300;
            ctx.moveTo(lx, ly);
            for(let j=0; j<5; j++) {
              lx += (Math.random()-0.5)*100;
              ly += 60;
              ctx.lineTo(lx, ly);
            }
            ctx.stroke();
          }
          ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)'; ctx.lineWidth = 3;
          for(let i=0; i<6; i++) {
             ctx.beginPath();
             const rot = (state.frame * 0.15) + (i * Math.PI * 0.33);
             ctx.arc(centerX, centerY, 80 + i * 35, rot, rot + 1.2);
             ctx.stroke();
          }
          ctx.restore();
        }
        drawBossSprite(ctx, e, stageId); 
        const introTaunt = (status === GameStatus.BOSS_INTRO && bossTauntText) ? bossTauntText : null;
        const currentTaunt = introTaunt || (state.bossVulgarityTimer > 0 ? state.bossLastVulgarity : null);
        if (currentTaunt) {
          ctx.save();
          ctx.font = 'bold 12px "Press Start 2P"';
          ctx.fillStyle = 'white';
          ctx.shadowColor = 'black';
          ctx.shadowBlur = 6;
          ctx.textAlign = 'center';
          ctx.fillText(currentTaunt, e.pos.x + e.width / 2, e.pos.y - 30);
          ctx.restore();
        }
      } 
      else { 
        if (e.enemyType === 'shield') { 
          ctx.fillStyle = '#444';
          ctx.fillRect(e.pos.x + 10, e.pos.y, e.width - 10, e.height);
          if (e.isShieldActive) {
            ctx.fillStyle = '#2C3E50'; 
            ctx.fillRect(e.pos.x, e.pos.y - 5, 15, e.height + 10);
            ctx.strokeStyle = '#00FFFF'; 
            ctx.lineWidth = 2;
            ctx.strokeRect(e.pos.x, e.pos.y - 5, 15, e.height + 10);
          } else {
            ctx.fillStyle = '#7F8C8D';
            ctx.fillRect(e.pos.x + 5, e.pos.y + 10, 10, e.height - 20);
          }
        } else if (e.id.startsWith('rusher')) {
          ctx.fillStyle = '#9B59B6'; 
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height);
        } else if (e.enemyType === 'flyer' && e.width > 60) {
            ctx.fillStyle = '#34495E'; 
            ctx.fillRect(e.pos.x, e.pos.y + 15, e.width, e.height - 30); 
        } else { 
          ctx.fillStyle = e.enemyType === 'flyer' ? COLORS.ENEMY_FLYER : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK); 
          ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); 
        } 
      }
      if (e.frozenTimer && e.frozenTimer > 0) { ctx.fillStyle = 'rgba(0, 255, 255, 0.4)'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, e.width + 10, e.height + 10); }
      if (!e.isBlownAway) { ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5); }
      ctx.restore();
    });
    if (status !== GameStatus.LEVEL_INTRO || gameStateRef.current.introTimer >= 80) {
      drawPlayer(ctx, player);

      if (state.playerLastVulgarity && state.playerVulgarityTimer > 0) {
        ctx.save();
        ctx.font = 'bold 10px "Press Start 2P"';
        ctx.fillStyle = 'white';
        ctx.shadowColor = 'black';
        ctx.shadowBlur = 4;
        ctx.textAlign = 'center';
        ctx.fillText(state.playerLastVulgarity, player.pos.x + player.width / 2, player.pos.y - 20);
        ctx.restore();
      }
    }
    projectiles.forEach(p => { 
        if (p.isBoulder) { 
            ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.pos.x * 0.05); 
            ctx.fillStyle = '#8B4513'; ctx.beginPath(); ctx.arc(0, 0, p.width/2, 0, Math.PI * 2); ctx.fill(); ctx.strokeStyle = 'black'; ctx.stroke(); ctx.restore(); 
        } else if (p.isShrapnel) {
            ctx.fillStyle = '#757575'; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); ctx.strokeStyle = 'black'; ctx.strokeRect(p.pos.x, p.pos.y, p.width, p.height);
        } else { 
            ctx.fillStyle = (p.isIce) ? COLORS.PROJECTILE_ICE : (p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY); 
            ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); 
        } 
    });
    particles.forEach(p => { 
      ctx.save();
      if (!p.isStuck) { ctx.globalAlpha = p.life < 100 ? p.life / 100 : 1; } 
      else { ctx.globalAlpha = 0.85; }
      ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); ctx.restore();
    });

    damageNumbers.forEach(d => {
      ctx.save();
      const alpha = d.life / d.maxLife;
      ctx.globalAlpha = alpha;
      ctx.font = `bold ${d.isCritical ? '24px' : '16px'} "Press Start 2P"`;
      ctx.fillStyle = d.isCritical ? '#FFD700' : (d.value > 50 ? '#FF4500' : '#FFFFFF');
      ctx.textAlign = 'center';
      ctx.fillText(d.value.toString(), d.pos.x, d.pos.y);
      ctx.restore();
    });

    ctx.restore();

    if (state.victoryString && (status === GameStatus.PLAYING || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.VICTORY)) { 
      ctx.save();
      ctx.font = 'bold 50px "Press Start 2P"'; 
      ctx.fillStyle = 'yellow'; 
      ctx.textAlign = 'center'; 
      ctx.strokeStyle = 'black';
      ctx.lineWidth = 4;
      ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
      ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); 
      ctx.restore();
    }

    if (state.deathTimer > 0) { 
      ctx.save();
      ctx.font = 'bold 60px "Press Start 2P"'; 
      ctx.fillStyle = '#FF0000'; 
      ctx.textAlign = 'center'; 
      ctx.fillText(state.deathString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); 
      ctx.restore();
    }
  }, [status, stageId, currentWeapon, invincibilityEnabled, jumpToBossEnabled, bossTauntText]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) {
      if (gameStateRef.current.frame === 0 && status === GameStatus.LEVEL_INTRO) {
        gameStateRef.current.victoryString = "";
        gameStateRef.current.postVictoryTimer = 0;
        gameStateRef.current.bossExplosionTimer = 0;
        gameStateRef.current.introTimer = 0; // Robust reset of intro state
        gameStateRef.current.particles = [];
        gameStateRef.current.projectiles = [];
        gameStateRef.current.pickups = [];
        gameStateRef.current.enemies = []; 
        gameStateRef.current.damageNumbers = [];
        gameStateRef.current.camera = { x: 0, y: 0 };

        // Reset player specific values for stage start
        gameStateRef.current.player.health = INITIAL_PLAYER_HEALTH;
        gameStateRef.current.player.killSatisfactionTimer = 0; // Expression reset to neutral
        gameStateRef.current.player.invincibilityTimer = 0;
        gameStateRef.current.player.pushbackTimer = 0;
        gameStateRef.current.player.isCharging = false;
        gameStateRef.current.player.isUppercutting = false;
        gameStateRef.current.playerStunTimer = 0;

        createLevel();
        gameStateRef.current.frame = 1;
      }
      frameId = window.requestAnimationFrame(loop);
    } else { 
      // Fully flush for menu/select
      gameStateRef.current.victoryString = "";
      gameStateRef.current.postVictoryTimer = 0;
      gameStateRef.current.bossExplosionTimer = 0;
      gameStateRef.current.introTimer = 0;
      gameStateRef.current.enemies = [];
      gameStateRef.current.particles = [];
      gameStateRef.current.projectiles = [];
      gameStateRef.current.camera = { x: 0, y: 0 };
      draw(); 
      gameStateRef.current.frame = 0; 
    }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel, initialAmmo, jumpToBossEnabled]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

