            {stageId && WEAPON_DESCRIPTIONS[stageId] && (
              <p className="text-white text-sm md:text-base font-bold italic tracking-tight leading-relaxed max-w-lg mx-auto">
                "{WEAPON_DESCRIPTIONS[stageId]}"
