            )}
          </div>
          <button 
            disabled={isInputLocked}
            onClick={onStart}
            className={`px-12 py-6 text-black text-xl font-black border-b-[8px] transition-all uppercase ${isInputLocked ? 'bg-gray-500 border-gray-700 opacity-50' : 'bg-yellow-500 hover:bg-yellow-400 border-yellow-800 active:translate-y-1 active:border-b-0'}`}
          >
            {isInputLocked ? 'INFUSING GAINS...' : 'fuck yeah'}
          </button>
        </div>
      )}

      {status === GameStatus.VICTORY && (
        <div className="animate-in fade-in duration-1000 max-w-xl bg-black/90 p-6 md:p-10 border-4 border-yellow-400 shadow-[0_0_50px_rgba(255,255,0,0.3)] flex flex-col items-center">
          <h2 className="text-2xl md:text-3xl text-yellow-400 mb-4 font-black tracking-tighter uppercase italic leading-none drop-shadow-md shrink-0">CONGRATULATIONS!!</h2>
          <div className="mb-6 max-h-[180px] md:max-h-[240px] overflow-y-auto bg-black/60 p-4 border border-white/10 rounded-sm custom-scrollbar w-full">
            <p className="text-white text-[9px] md:text-[10px] uppercase font-black tracking-normal leading-relaxed text-left">
              Good job, Meathead. Your quest to just fucking kill everyone in sight paid off. Local counter terrorism units identified the men you killed as "The Four Assholes." These guys were going to use their super powers to destroy the world through manipulation of natural disasters. Luckily for us, they happened to be in your way. You saved the world! Wanna try again?
            </p>
          </div>
          <button 
            disabled={isInputLocked}
            onClick={onStart} 
            className={`w-full py-5 text-black font-black border-b-[8px] text-lg shadow-xl transition-all shrink-0 ${isInputLocked ? 'bg-gray-700 border-gray-900 opacity-50 text-gray-500' : 'bg-yellow-400 hover:bg-yellow-300 border-yellow-700 active:translate-y-1 active:border-b-0'}`}
          >
            {isInputLocked ? 'WAITING...' : 'SURE'}
          </button>
        </div>
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 8px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: rgba(0, 0, 0, 0.4);
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #3b82f6;
          border-radius: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #60a5fa;
        }
        .text-shadow-glow {
          text-shadow: 0 0 10px rgba(255, 255, 255, 0.5);
        }
      `}</style>
    </div>
  );
};

