const Overlay: React.FC<OverlayProps> = ({ 
  status, onStart, onResume, onBossSelect, onQuitToMenu, onSelectStage, onCheatAllWeapons, onToggleInvincibility, onToggleInfiniteAmmo, onToggleJumpToBoss,
  cheatEnabled, invincibilityEnabled, infiniteAmmoEnabled, jumpToBossEnabled, showCheats = false, bossTaunt, briefing, defeatedStages = [], selectedIndex, overlayActiveTime, stageId 
}) => {
  const isInputLocked = overlayActiveTime < 2000;

  const handleSelect = (id: string) => {
    if (onSelectStage) {
      onSelectStage(id);
    }
  };

  if (status === GameStatus.PLAYING || status === GameStatus.LEVEL_INTRO || status === GameStatus.BOSS_TRANSITION) return null;

  return (
    <div className="absolute inset-0 bg-black/95 flex flex-col items-center justify-center z-50 p-6 text-center overflow-hidden">
      {status === GameStatus.START && (
        <>
          {showCheats && (
            <div className="absolute top-6 right-6 z-[60] flex flex-col gap-2 items-end">
              <button 
                  onClick={onCheatAllWeapons}
                  className={`px-4 py-2 border-2 transition-all font-black text-[9px] uppercase shadow-[2px_2px_0px_white] hover:scale-105 active:translate-y-0.5 ${cheatEnabled ? 'bg-yellow-500 border-white text-black shadow-[2px_2px_0px_#fff]' : 'bg-gray-800 border-gray-600 text-gray-400 shadow-[2px_2px_0px_#333]'}`}
                >
                  ALL WEAPONS: {cheatEnabled ? 'ON' : 'OFF'}
                </button>
                <button 
                  onClick={onToggleInvincibility}
                  className={`px-4 py-2 border-2 transition-all font-black text-[9px] uppercase shadow-[2px_2px_0px_white] hover:scale-105 active:translate-y-0.5 ${invincibilityEnabled ? 'bg-green-500 border-white text-black shadow-[2px_2px_0px_#fff]' : 'bg-gray-800 border-gray-600 text-gray-400 shadow-[2px_2px_0px_#333]'}`}
                >
                  INVINCIBILITY: {invincibilityEnabled ? 'ON' : 'OFF'}
                </button>
                <button 
                  onClick={onToggleInfiniteAmmo}
                  className={`px-4 py-2 border-2 transition-all font-black text-[9px] uppercase shadow-[2px_2px_0px_white] hover:scale-105 active:translate-y-0.5 ${infiniteAmmoEnabled ? 'bg-blue-500 border-white text-black shadow-[2px_2px_0px_#fff]' : 'bg-gray-800 border-gray-600 text-gray-400 shadow-[2px_2px_0px_#333]'}`}
                >
                  INFINITE AMMO: {infiniteAmmoEnabled ? 'ON' : 'OFF'}
                </button>
                <button 
                  onClick={onToggleJumpToBoss}
                  className={`px-4 py-2 border-2 transition-all font-black text-[9px] uppercase shadow-[2px_2px_0px_white] hover:scale-105 active:translate-y-0.5 ${jumpToBossEnabled ? 'bg-red-500 border-white text-black shadow-[2px_2px_0px_#fff]' : 'bg-gray-800 border-gray-600 text-gray-400 shadow-[2px_2px_0px_#333]'}`}
                >
                  JUMP TO BOSS: {jumpToBossEnabled ? 'ON' : 'OFF'}
                </button>
            </div>
          )}

          <div className="animate-in fade-in zoom-in duration-700 max-w-lg relative w-full h-full flex flex-col items-center justify-center pt-8">
