            <h1 className="text-4xl md:text-5xl text-red-600 mb-2 font-black tracking-tighter drop-shadow-[4px_4px_0px_white]">MEATHEAD</h1>
            <div className="text-white text-[9px] mb-6 border-y border-red-900 py-3 px-4 italic uppercase tracking-tight leading-relaxed max-w-sm mx-auto">
              MISSION: {briefing}
            </div>
            <div className="flex flex-col gap-4">
              <button 
                disabled={isInputLocked}
                onClick={onStart}
                className={`px-10 py-4 text-white text-xl border-b-[8px] transition-all font-black uppercase ring-4 ring-white/10 ${isInputLocked ? 'bg-gray-700 border-gray-900 opacity-50 cursor-not-allowed' : 'bg-red-700 hover:bg-red-500 border-red-900 active:translate-y-1 active:border-b-0'}`}
              >
                {isInputLocked ? 'READYING PUMP...' : 'BEGIN THE PUMP'}
              </button>
            </div>
            <ControlsGuide />
          </div>
        </>
      )}

      {status === GameStatus.STAGE_SELECT && (
        <div className="w-full h-full flex flex-col items-center justify-center animate-in slide-in-from-bottom-8 duration-500">
          <h2 className="text-2xl md:text-3xl text-white mb-8 font-black tracking-widest border-b-4 border-red-600 pb-2 uppercase italic text-shadow-glow">TARGET SELECTION</h2>
          <div className="grid grid-cols-2 gap-x-12 gap-y-6">
            {STAGES.map((stage, idx) => {
              const isDefeated = defeatedStages.includes(stage.id);
              const isSelected = idx === selectedIndex;
              return (
                <button
                  key={stage.id}
                  onClick={() => handleSelect(stage.id)}
                  className={`w-40 h-52 md:w-48 md:h-64 ${isDefeated ? 'opacity-40 grayscale' : ''} border-4 ${isSelected ? 'border-yellow-400 scale-110 shadow-[0_0_25px_rgba(255,255,0,0.6)] z-10' : 'border-white/40'} bg-[#2C2C2C] transition-all flex flex-col overflow-hidden group shadow-lg rounded-sm`}
                >
                  <div className="flex-1 bg-black relative overflow-hidden">
                    <BossPortrait id={stage.id} />
                    {isDefeated && (
                      <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-20">
                         <div className="text-red-500 text-[12px] font-black rotate-[-25deg] border-4 border-red-600 p-2 uppercase tracking-tighter bg-black/40">
                           DEAD AS SHIT
                         </div>
                      </div>
                    )}
                  </div>

                  <div className={`p-2 py-3 flex flex-col items-center justify-center ${isSelected ? 'bg-yellow-400' : 'bg-white'}`}>
                    <span className="text-black text-[10px] font-black uppercase leading-tight text-center">
                      {stage.id}
                    </span>
                  </div>
                </button>
              );
