          <div className="grid grid-cols-2 gap-x-12 gap-y-6">
            {STAGES.map((stage, idx) => {
              const isDefeated = defeatedStages.includes(stage.id);
              const isSelected = idx === selectedIndex;
              return (
                <button
                  key={stage.id}
                  onClick={() => handleSelect(stage.id)}
                  className={`w-40 h-52 md:w-48 md:h-64 ${isDefeated ? 'opacity-40 grayscale' : ''} border-4 ${isSelected ? 'border-yellow-400 scale-110 shadow-[0_0_25px_rgba(255,255,0,0.6)] z-10' : 'border-white/40'} bg-[#2C2C2C] transition-all flex flex-col overflow-hidden group shadow-lg rounded-sm`}
                >
                  <div className="flex-1 bg-black relative overflow-hidden">
                    <BossPortrait id={stage.id} />
                    {isDefeated && (
                      <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-20">
                         <div className="text-red-500 text-[12px] font-black rotate-[-25deg] border-4 border-red-600 p-2 uppercase tracking-tighter bg-black/40">
                           DEAD AS SHIT
                         </div>
                      </div>
                    )}
                  </div>

                  <div className={`p-2 py-3 flex flex-col items-center justify-center ${isSelected ? 'bg-yellow-400' : 'bg-white'}`}>
                    <span className="text-black text-[10px] font-black uppercase leading-tight text-center">
                      {stage.id}
                    </span>
                  </div>
                </button>
              );
            })}
          </div>
          <div className="mt-8 text-[10px] text-yellow-400 animate-pulse uppercase font-black tracking-widest bg-black/50 px-4 py-1 border border-yellow-400/30">
            CHOOSE YOUR GAINS
          </div>
        </div>
      )}

      {status === GameStatus.PAUSED && (
        <div className="animate-in fade-in duration-200">
           <h2 className="text-4xl text-white mb-10 font-black uppercase tracking-widest italic border-b-4 border-yellow-500 pb-4">RESTING SET</h2>
           <div className="flex flex-col gap-6">
              <button 
                onClick={onResume}
                className={`px-10 py-4 bg-yellow-600 hover:bg-yellow-500 text-white text-xl font-black border-b-[8px] border-yellow-800 transition-all uppercase ${selectedIndex === 0 ? 'ring-4 ring-white scale-110' : ''}`}
              >
                RESUME
              </button>
              <button 
                onClick={onBossSelect}
                className={`px-10 py-4 bg-red-700 hover:bg-red-600 text-white text-xl font-black border-b-[8px] border-red-900 transition-all uppercase ${selectedIndex === 1 ? 'ring-4 ring-white scale-110' : ''}`}
              >
                BOSS SELECT
              </button>
              <button 
                onClick={onQuitToMenu}
                className={`px-10 py-4 bg-gray-700 hover:bg-gray-600 text-white text-xl font-black border-b-[8px] border-gray-900 transition-all uppercase ${selectedIndex === 2 ? 'ring-4 ring-white scale-110' : ''}`}
              >
                QUIT TO MENU
              </button>
           </div>
        </div>
      )}

      {status === GameStatus.BOSS_INTRO && (
        <div className="bg-red-950/90 border-4 border-red-600 p-6 max-w-lg animate-in fade-in slide-in-from-top-4 duration-500 shadow-[0_0_40px_rgba(255,0,0,0.4)]">
          <h2 className="text-xl md:text-2xl text-red-500 mb-4 font-black tracking-tighter italic uppercase underline decoration-2">ENEMY LOG:</h2>
          <div className="max-h-32 overflow-y-auto mb-6 px-4 text-left border-l-4 border-red-500 bg-black/40 py-4 custom-scrollbar">
            <p className="text-white italic text-sm md:text-base leading-snug uppercase tracking-tight">"{bossTaunt}"</p>
          </div>
          <button 
            disabled={isInputLocked}
            onClick={onStart}
            className={`px-8 py-4 text-white text-lg font-black border-b-[6px] transition-all uppercase ${isInputLocked ? 'bg-gray-700 border-gray-900 opacity-50' : 'bg-red-600 hover:bg-red-500 border-red-900 active:translate-y-1 active:border-b-0'}`}
          >
            {isInputLocked ? 'LISTENING...' : 'STFU AND DIE'}
          </button>
        </div>
      )}

      {status === GameStatus.BOSS_VICTORY_SPEECH && (
        <div className="bg-blue-900/95 border-8 border-blue-400 p-6 max-w-2xl animate-in fade-in zoom-in duration-500 shadow-[0_0_60px_rgba(0,255,0,0.4)]">
          <h2 className="text-3xl md:text-5xl text-yellow-400 mb-6 font-black uppercase tracking-widest italic shrink-0 underline decoration-4 underline-offset-4">GAINS</h2>
          <div className="mb-8 pr-4 text-center bg-black/50 p-8 rounded-lg border-2 border-white/10 flex flex-col gap-4">
            <p className="text-yellow-400 text-xl md:text-2xl font-black uppercase tracking-tighter leading-none">
              You have gained {stageId ? WEAPON_NAMES[stageId] : 'NEW MUSCLES'}
            </p>
            {stageId && WEAPON_DESCRIPTIONS[stageId] && (
              <p className="text-white text-sm md:text-base font-bold italic tracking-tight leading-relaxed max-w-lg mx-auto">
                "{WEAPON_DESCRIPTIONS[stageId]}"
              </p>
            )}
          </div>
          <button 
            disabled={isInputLocked}
            onClick={onStart}
            className={`px-12 py-6 text-black text-xl font-black border-b-[8px] transition-all uppercase ${isInputLocked ? 'bg-gray-500 border-gray-700 opacity-50' : 'bg-yellow-500 hover:bg-yellow-400 border-yellow-800 active:translate-y-1 active:border-b-0'}`}
          >
            {isInputLocked ? 'INFUSING GAINS...' : 'fuck yeah'}
          </button>
        </div>
      )}

      {status === GameStatus.VICTORY && (
        <div className="animate-in fade-in duration-1000 max-w-xl bg-black/90 p-6 md:p-10 border-4 border-yellow-400 shadow-[0_0_50px_rgba(255,255,0,0.3)] flex flex-col items-center">
          <h2 className="text-2xl md:text-3xl text-yellow-400 mb-4 font-black tracking-tighter uppercase italic leading-none drop-shadow-md shrink-0">CONGRATULATIONS!!</h2>
          <div className="mb-6 max-h-[180px] md:max-h-[240px] overflow-y-auto bg-black/60 p-4 border border-white/10 rounded-sm custom-scrollbar w-full">
            <p className="text-white text-[9px] md:text-[10px] uppercase font-black tracking-normal leading-relaxed text-left">
              Good job, Meathead. Your quest to just fucking kill everyone in sight paid off. Local counter terrorism units identified the men you killed as "The Four Assholes." These guys were going to use their super powers to destroy the world through manipulation of natural disasters. Luckily for us, they happened to be in your way. You saved the world! Wanna try again?
            </p>
          </div>
          <button 
            disabled={isInputLocked}
            onClick={onStart} 
            className={`w-full py-5 text-black font-black border-b-[8px] text-lg shadow-xl transition-all shrink-0 ${isInputLocked ? 'bg-gray-700 border-gray-900 opacity-50 text-gray-500' : 'bg-yellow-400 hover:bg-yellow-300 border-yellow-700 active:translate-y-1 active:border-b-0'}`}
          >
            {isInputLocked ? 'WAITING...' : 'SURE'}
          </button>
        </div>
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 8px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: rgba(0, 0, 0, 0.4);
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #3b82f6;
          border-radius: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #60a5fa;
        }
        .text-shadow-glow {
          text-shadow: 0 0 10px rgba(255, 255, 255, 0.5);
        }
      `}</style>
    </div>
  );
};

