  }, [status, stageId, onPlayerUpdate, onBossEncounter, onBossDefeated, onBossDeath, onGameOver, onIntroComplete, onBossTransition, onTogglePause, currentWeapon, respawn, invincibilityEnabled, infiniteAmmoEnabled, jumpToBossEnabled]);

  const drawPlayer = (ctx: CanvasRenderingContext2D, p: Player & { killSatisfactionTimer: number }) => {
