              if (stageId === 'Artie Avalanche' && isWeak && enemy.health > 0) {
                  enemy.vel.y = -15; 
                  enemy.vel.x = (enemy.pos.x < player.pos.x ? -1 : 1) * 10;
                  enemy.bossState = 'jumping';
                  enemy.stateTimer = 40;
              }
              if (enemy.health <= 0) triggerBossDeath(enemy, p.vel.x > 0 ? 1 : -1, isWeak);
            } else {
              enemy.health -= p.damage; if (p.isIce) enemy.frozenTimer = SHOTGUN_FREEZE_TIME;
              spawnDamageNumber(enemy.pos, p.damage, p.isBoulder);
              if (enemy.health <= 0) { 
                spawnDeathShower(enemy.pos, 0, 1.2); 
                spawnPickup(enemy.pos); 
                let cat: VulgarityType = 'gun_kill';
                if (p.isBoulder) cat = 'boulder_kill';
                else if (p.isIce) cat = 'shotgun_kill';
                speakVulgarity(cat);
                player.killSatisfactionTimer = 60; 
              }
            }
            if (p.isBoulder) {
               spawnRockShatter({ x: p.pos.x + p.width / 2, y: p.pos.y + p.height / 2 });
               spawnBoulderShrapnel({ x: p.pos.x + p.width / 2, y: p.pos.y + p.height / 2 }, 12, p.vel.x > 0 ? 1 : -1);
            }
            return false;
          }
        }
      } else if (!player.isCharging && !player.isUppercutting && player.invincibilityTimer <= 0 && p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < currentPosY + currentHeight && p.pos.y + p.height > currentPosY) {
          if (!invincibilityEnabled) player.health -= (p.damage / 2);
          player.invincibilityTimer = 60; speakVulgarity('hurt'); player.pushbackTimer = 20;
          if (p.isBoulder) spawnRockShatter({ x: p.pos.x + p.width / 2, y: p.pos.y + p.height / 2 });
          return false;
      }
      return true;
    });

    state.pickups = pickups.filter(p => {
      p.vel.y += GRAVITY; p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.vel.x *= 0.9; p.life--;
      blocks.forEach(block => { if (block.type !== 'pit' && p.pos.x < block.x + block.w && p.pos.x + p.width > block.x && p.pos.y < block.y + block.h && p.pos.y + p.height > block.y) { p.pos.y = block.y - p.height; p.vel.y = 0; } });
      if (p.pos.x < player.pos.x + player.width && p.pos.x + p.width > player.pos.x && p.pos.y < player.pos.y + player.height && p.pos.y + p.height > player.pos.y) {
        if (p.type.includes('health')) player.health = Math.min(player.maxHealth, player.health + (p.type === 'large_health' ? 50 : 20));
        else {
            const pct = p.type === 'large_ammo' ? AMMO_PICKUP_PCT.LARGE : AMMO_PICKUP_PCT.SMALL;
            let target = player.currentWeapon === 'GUN' ? (Object.keys(player.weaponAmmo) as WeaponType[]).find(w => w !== 'GUN' && player.weaponAmmo[w] < MAX_AMMO[w]) || 'BOULDER' : player.currentWeapon;
            if (target !== 'GUN') player.weaponAmmo[target] = Math.min(MAX_AMMO[target], player.weaponAmmo[target] + MAX_AMMO[target] * pct);
        }
        return false;
      }
      return p.life > 0;
    });

