  currentWeapon, initialAmmo, invincibilityEnabled, infiniteAmmoEnabled, jumpToBossEnabled,
  bossTauntText
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player',
      pos: { x: 150, y: 100 },
      vel: { x: 0, y: 0 },
      width: 44,
      height: 64,
      health: INITIAL_PLAYER_HEALTH,
      maxHealth: INITIAL_PLAYER_HEALTH,
      type: 'player',
      isCharging: false,
      isUppercutting: false,
      isDucking: false,
      specialCharges: MAX_SPECIAL_CHARGES,
      specialChargeTimer: 0,
      chargeDuration: 0,
      isJumping: false,
      isGrounded: false,
      facing: 1,
      shootCooldown: 0,
      jumpPrepTimer: 0,
      landTimer: 0,
      invincibilityTimer: 0,
      pushbackTimer: 0,
      killSatisfactionTimer: 0,
      hasUsedAirMove: false,
      jumpInputReleased: true,
      chargeInputReleased: true,
      currentWeapon: 'GUN',
      availableWeapons: ['GUN'],
      weaponAmmo: { ...initialAmmo }
    } as Player & { killSatisfactionTimer: number },
    enemies: [] as (Enemy & { bossState?: 'idle' | 'jumping' | 'attacking' | 'hurricane' | 'telegraphing' | 'stunned_drop', stateTimer?: number, jumpCount?: number, pauseTimer?: number, isGroundedBoss?: boolean, sideTimer?: number, said75?: boolean, said50?: boolean, said25?: boolean })[],
    projectiles: [] as Projectile[],
    pickups: [] as Pickup[],
    particles: [] as (Particle & { isWater?: boolean })[],
    damageNumbers: [] as DamageNumber[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    bossSpawned: false,
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    playerLastVulgarity: "",
    playerVulgarityTimer: 0,
    bossLastVulgarity: "",
    bossVulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryString: "",
    deathString: "",
    deathTimer: 0,
    postVictoryTimer: 0,
    introTimer: 0,
    bossExplosionTimer: 0,
    bossExplosionPos: { x: 0, y: 0 },
