    if (window.speechSynthesis.speaking) return;
    if (state.voiceLineCooldown > 0) return;

    let pool = GUN_KILL_VULGARITIES;
    if (category === 'hurt') {
      if (state.arenaLocked && stageId && BOSS_HURT_VULGARITIES[stageId]) {
        pool = BOSS_HURT_VULGARITIES[stageId];
      } else {
        pool = HURT_VULGARITIES;
      }
    }
    if (category === 'death') pool = DEATH_VULGARITIES;
    if (category === 'charge_kill') pool = CHARGE_KILL_VULGARITIES;
    if (category === 'uppercut_kill') pool = UPPERCUT_KILL_VULGARITIES;
    if (category === 'boulder_kill') pool = BOULDER_KILL_VULGARITIES;
    if (category === 'shotgun_kill') pool = SHOTGUN_KILL_VULGARITIES;
    if (category === 'flamethrower_kill') pool = FLAMETHROWER_KILL_VULGARITIES;
    if (category === 'tsunami_kill') pool = TSUNAMI_KILL_VULGARITIES;

    const text = pool[Math.floor(Math.random() * pool.length)];
    state.playerLastVulgarity = text;
    state.playerVulgarityTimer = 120;

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.pitch = 0.1; 
