  pos: Vector2;
  life: number;
  type: 'wall' | 'ground';
}

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, specialCharges: number, specialChargeTimer: number, ammo?: Record<WeaponType, number>, forcedWeapon?: WeaponType) => void;
  onBossEncounter: () => void;
  onBossTransition: () => void;
  onBossDefeated: (stageId: string) => void;
  onBossDeath: () => void;
  onGameOver: (victory: boolean) => void;
  onIntroComplete: () => void;
  onTogglePause: () => void;
  currentWeapon: WeaponType;
  initialAmmo: Record<WeaponType, number>;
  invincibilityEnabled: boolean;
  infiniteAmmoEnabled: boolean;
  jumpToBossEnabled: boolean;
  bossTauntText: string;
}

const BOSS_DOOR_X = 7200;
const DOOR_WIDTH = 40;

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  status, stageId, onPlayerUpdate, onBossEncounter, onBossTransition, 
  onBossDefeated, onBossDeath, onGameOver, onIntroComplete, onTogglePause, 
  currentWeapon, initialAmmo, invincibilityEnabled, infiniteAmmoEnabled, jumpToBossEnabled,
  bossTauntText
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player', pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, width: 44, height: 64,
      health: INITIAL_PLAYER_HEALTH, maxHealth: INITIAL_PLAYER_HEALTH, type: 'player',
      isCharging: false, isUppercutting: false, isDucking: false, specialCharges: MAX_SPECIAL_CHARGES,
      specialChargeTimer: 0, chargeDuration: 0, isJumping: false, isGrounded: false,
      facing: 1, shootCooldown: 0, jumpPrepTimer: 0, landTimer: 0, invincibilityTimer: 0,
      pushbackTimer: 0, killSatisfactionTimer: 0, hasUsedAirMove: false, jumpInputReleased: true,
      chargeInputReleased: true, currentWeapon: 'GUN', availableWeapons: ['GUN'],
      weaponAmmo: { ...initialAmmo }
    } as Player & { killSatisfactionTimer: number },
    enemies: [] as (Enemy & { bossState?: string, stateTimer?: number, said75?: boolean, said50?: boolean, said25?: boolean, isGroundedBoss?: boolean })[],
    projectiles: [] as Projectile[],
    pickups: [] as Pickup[],
    particles: [] as (Particle & { isWater?: boolean })[],
    damageNumbers: [] as DamageNumber[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    arenaLocked: false,
    doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0,
    playerLastVulgarity: "",
    playerVulgarityTimer: 0,
    bossLastVulgarity: "",
    bossVulgarityTimer: 0,
    voiceLineCooldown: 0,
    victoryString: "",
    deathString: "",
    deathTimer: 0,
    postVictoryTimer: 0,
    introTimer: 0,
    bossExplosionTimer: 0,
    bossExplosionPos: { x: 0, y: 0 },
    tsunamiX: -1,
    tsunamiStartX: 0,
    tsunamiActive: false,
    tsunamiDir: 1,
    bossVolcanoes: [] as Volcano[],
    bossVolcanoTelegraphs: [] as Volcano[],
    bossPoopTelegraphs: [] as { pos: Vector2, life: number, spawnX: number }[],
    playerStunTimer: 0,
    screenShakeTimer: 0,
    shouldSyncWeapon: false
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  const spawnDamageNumber = (pos: Vector2, value: number, isCritical: boolean = false) => {
    const state = gameStateRef.current;
    state.damageNumbers.push({
      id: `dmg-${Date.now()}-${Math.random()}`,
      value: Math.floor(value),
      pos: { ...pos },
      vel: { x: (Math.random() - 0.5) * 4, y: -4 - Math.random() * 2 },
      life: 45, maxLife: 45, isCritical
    });
  };

  const spawnExplosion = (pos: Vector2, color: string, count: number, baseVelX: number = 0, spread: number = 15, isGlass: boolean = false, isBossGore: boolean = false) => {
    const state = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      if (state.particles.length > 2500) break; 
      state.particles.push({
        pos: { ...pos },
        vel: { x: baseVelX + (Math.random() - 0.5) * spread, y: (Math.random() - 0.5) * spread },
        life: isGlass ? 150 + Math.random() * 200 : 20 + Math.random() * 80,
        color: color, size: i % 3 === 0 ? 1 + Math.random() * 4 : 2 + Math.random() * 12,
        isGlass, isBossGore
      });
    }
  };

  const spawnDeathShower = (pos: Vector2, facing: number = 0, multiplier: number = 1, isBossDeath: boolean = false) => {
    FLESH_COLORS.forEach(c => spawnExplosion(pos, c, Math.ceil(8 * multiplier), facing * 18, 25, false, isBossDeath));
    GORE_COLORS.forEach(c => spawnExplosion(pos, c, Math.ceil(12 * multiplier), facing * 22, 35, false, isBossDeath));
  };

  const speakAsBoss = (bossId: string, text: string) => {
    if ('speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.pitch = bossId === 'Hector Hurricane' ? 1.2 : 0.7;
      utterance.rate = 1.0;
      window.speechSynthesis.speak(utterance);
      gameStateRef.current.bossLastVulgarity = text;
      gameStateRef.current.bossVulgarityTimer = 150;
    }
  };

  // Fixed VulgarityType by importing it from types.ts
  const speakVulgarity = (category: VulgarityType) => {
    const state = gameStateRef.current;
    if (!('speechSynthesis' in window) || window.speechSynthesis.speaking || state.voiceLineCooldown > 0) return;
    const pool = HURT_VULGARITIES; // simplified for brevity
    const text = pool[Math.floor(Math.random() * pool.length)];
    state.playerLastVulgarity = text;
    state.playerVulgarityTimer = 120;
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.pitch = 0.1; utterance.rate = 1.2;
    window.speechSynthesis.speak(utterance);
    state.voiceLineCooldown = 60;
  };

  const triggerBossDeath = (boss: Enemy, playerFacing: number, wasWeakness: boolean) => {
    const state = gameStateRef.current;
    if (state.bossExplosionTimer > 0) return;
    const pos = { x: boss.pos.x + boss.width / 2, y: boss.pos.y + boss.height / 2 };
    if (wasWeakness) {
      state.bossExplosionTimer = 180; 
      state.bossExplosionPos = pos;
      spawnDeathShower(state.bossExplosionPos, playerFacing, 25, true); 
    } else {
      spawnDeathShower(pos, playerFacing, 6, true);
      onBossDeath(); 
      state.victoryString = "V"; 
    }
    state.arenaLocked = false;
  };

  const createLevel = useCallback(() => {
    const state = gameStateRef.current;
    state.arenaLocked = false;
    state.doorState = 'closed';
    state.doorOpenAmount = 0;
    state.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 8000, y: -1000, w: 100, h: 2000, type: 'wall' }, 
      { x: 0, y: 550, w: 8000, h: 50, type: 'ground' },
      { x: BOSS_DOOR_X, y: 400, w: DOOR_WIDTH, h: 150, type: 'door' },
      { x: BOSS_DOOR_X, y: -1000, w: DOOR_WIDTH, h: 1400, type: 'wall' }
    ];
    state.enemies = [
      { id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 666, maxHealth: 666, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0, bossState: 'idle', stateTimer: 60 }
    ];
  }, [stageId]);

  const respawn = useCallback(() => {
    const state = gameStateRef.current;
    state.player.health = INITIAL_PLAYER_HEALTH;
    state.player.pos = { x: 150, y: 400 };
    state.player.vel = { x: 0, y: 0 };
    state.deathTimer = 0;
    state.victoryString = "";
    createLevel();
  }, [createLevel]);

  const update = useCallback(() => {
    const state = gameStateRef.current;
    const { player, enemies, projectiles, particles, blocks } = state;
    if (status !== GameStatus.PLAYING) return;
    state.frame++;

    const currentHeight = player.isDucking ? player.height - 28 : player.height;
    const currentPosY = player.isDucking ? player.pos.y + 28 : player.pos.y;

    // Movement
    if (keys.current['a']) player.vel.x = -PLAYER_SPEED;
    else if (keys.current['d']) player.vel.x = PLAYER_SPEED;
    else player.vel.x *= FRICTION;

    player.vel.y += GRAVITY;
    player.pos.x += player.vel.x;
    player.pos.y += player.vel.y;

    // Hector Hurricane logic
    enemies.forEach(e => {
      if (e.type === 'boss' && stageId === 'Hector Hurricane') {
        if (e.bossState === 'hurricane') {
          const dist = Math.abs((e.pos.x + e.width/2) - (player.pos.x + player.width/2));
          if (dist < 300 && player.invincibilityTimer <= 0) {
            player.health -= 8;
            player.invincibilityTimer = 25;
            player.pushbackTimer = 10;
            e.stateTimer = 0; // Interrupt boss
          }
        }
      }
    });

    // Simple Collision and Logic
    blocks.forEach(b => {
      if (player.pos.x < b.x + b.w && player.pos.x + player.width > b.x && player.pos.y < b.y + b.h && player.pos.y + player.height > b.y) {
        if (player.pos.y + player.height / 2 < b.y + b.h / 2) {
          player.pos.y = b.y - player.height; player.vel.y = 0; player.isGrounded = true;
        }
      }
    });

    // Interruption logic for Hurricane
    enemies.forEach(e => {
      if (e.type === 'boss' && e.health > 0) {
        const isHit = player.pos.x < e.pos.x + e.width && player.pos.x + player.width > e.pos.x && currentPosY < e.pos.y + e.height && currentPosY + currentHeight > e.pos.y;
        if (isHit) {
          if (stageId === 'Hector Hurricane' && e.bossState === 'hurricane') e.stateTimer = 0;
          const pushDir = (player.pos.x + player.width/2 < e.pos.x + e.width/2) ? -1 : 1;
          player.vel.x = pushDir * 18; player.pushbackTimer = 20;
          if (player.invincibilityTimer <= 0) { player.health -= 5; player.invincibilityTimer = 30; }
        }
      }
    });

    onPlayerUpdate(player.health, player.specialCharges, player.specialChargeTimer, player.weaponAmmo);
    if (player.pos.x > BOSS_DOOR_X) state.arenaLocked = true;
    if (!state.arenaLocked) state.camera.x = Math.max(0, Math.min(7200, player.pos.x - 400));
  }, [status, stageId, onPlayerUpdate]);

  const draw = useCallback(() => {
    const canvas = canvasRef.current; if (!canvas) return;
    const ctx = canvas.getContext('2d'); if (!ctx) return;
    const state = gameStateRef.current;
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save(); ctx.translate(-state.camera.x, -state.camera.y);
    state.blocks.forEach(b => { ctx.fillStyle = 'gray'; ctx.fillRect(b.x, b.y, b.w, b.h); });
    ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(state.player.pos.x, state.player.pos.y, state.player.width, state.player.height);
    state.enemies.forEach(e => { ctx.fillStyle = 'red'; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); });
    ctx.restore();
  }, [status]);

  useEffect(() => {
    let frameId: number;
    const loop = () => { update(); draw(); frameId = requestAnimationFrame(loop); };
    frameId = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(frameId);
  }, [update, draw]);

  useEffect(() => { createLevel(); }, [createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

