                  if (e.stateTimer <= 0) {
                    e.bossState = 'idle';
                    e.stateTimer = 40;
                    state.bossPoopTelegraphs = [];
                  }
                } else if (e.bossState === 'jumping') {
                  if (e.isGroundedBoss) {
                    e.bossState = 'hurricane';
                    e.stateTimer = 300;
                    e.vel.x = 0;
                  }
